mapper.select:
SELECT a.mime_type, a.audio_data
FROM session_audios a
INNER JOIN training_sessions s ON s.session_id = a.session_id
INNER JOIN analysis_reports r ON r.session_id = s.session_id
WHERE r.report_id = #{reportId}
  AND s.user_id = #{userId}

SELECT total_session_count, total_duration_seconds, average_score
FROM v_user_training_stats
WHERE user_id = #{userId}

mapper.insert:
INSERT INTO training_sessions (
  user_id, topic_id, status, started_at, ended_at, duration_seconds, created_at
) VALUES (
  #{userId}, #{topicId}, 'completed', #{startedAt}, #{endedAt}, #{durationSeconds}, #{startedAt}
)

INSERT INTO analysis_reports (
  session_id, total_score, speech_rate, pause_count, fluency_score, result_label, transcript,
  content_score, content_summary, analyzed_at
) VALUES (
  #{sessionId}, #{totalScore}, #{speechRate}, #{pauseCount}, #{fluencyScore}, #{resultLabel}, #{transcript},
  #{contentScore}, #{contentSummary}, #{analyzedAt}
)

INSERT INTO training_sessions (
  user_id, topic_id, status, started_at, duration_seconds, created_at
) VALUES (
  #{userId}, #{topicId}, 'recording', #{startedAt}, 0, #{startedAt}
)

mapper.select:
SELECT a.mime_type, a.audio_data
FROM session_audios a
INNER JOIN training_sessions s ON s.session_id = a.session_id
WHERE a.session_id = #{sessionId}
  AND s.user_id = #{userId}

mapper.delete:
DELETE FROM training_sessions
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
  AND status <> 'completed'
